{
  "status": "graded",
  "criteria": [
    {
      "criterion_id": "c1",
      "level_id": "met",
      "reason": "明确要求通过环境、关卡和随机种子隔离训练与评估。",
      "evidence_quote": "Separate training and evaluation through clearly defined environments, levels and random seeds.",
      "evidence_source": "text"
    },
    {
      "criterion_id": "c2",
      "level_id": "met",
      "reason": "明确要求冻结评估策略模式，包括探索 epsilon。",
      "evidence_quote": "Freeze the evaluation policy mode, including any exploration epsilon.",
      "evidence_source": "text"
    },
    {
      "criterion_id": "c3",
      "level_id": "met",
      "reason": "要求使用多个种子并报告均值和波动，而非最佳单次结果。",
      "evidence_quote": "Use multiple seeds and report their mean and variability, not the best run.",
      "evidence_source": "text"
    },
    {
      "criterion_id": "c4",
      "level_id": "met",
      "reason": "指标包含回报、成功率、回合长度、约束违反和资源使用。",
      "evidence_quote": "Include return, success, episode length, constraint violations and resource use.",
      "evidence_source": "text"
    },
    {
      "criterion_id": "c5",
      "level_id": "met",
      "reason": "要求用标准误或置信/bootstrap 区间量化不确定性。",
      "evidence_quote": "Quantify uncertainty using standard errors or confidence/bootstrap intervals.",
      "evidence_source": "text"
    },
    {
      "criterion_id": "c6",
      "level_id": "met",
      "reason": "要求与随机、启发式、已有和无学习基线比较。",
      "evidence_quote": "Compare against suitable random, heuristic, established and no-learning baselines.",
      "evidence_source": "text"
    },
    {
      "criterion_id": "c7",
      "level_id": "met",
      "reason": "要求消融所提组件以检验改进的声称原因。",
      "evidence_quote": "Ablate the proposed components to test the claimed cause of improvement.",
      "evidence_source": "text"
    },
    {
      "criterion_id": "c8",
      "level_id": "met",
      "reason": "要求记录失败、异常轨迹和分布外行为。",
      "evidence_quote": "Document failures, unusual trajectories and behavior outside the training distribution.",
      "evidence_source": "text"
    }
  ]
}
